def roots_scan(fn,lo,hi,count=1800):
 roots=[];prev=lo;pv=fn(prev)
 for i in range(1,count+1):
  q=lo+(hi-lo)*i/count;val=fn(q)
  if val*pv<0:
   root=float(mp.findroot(fn,(prev,q)))
   if not roots or abs(root-roots[-1])>1e-6:roots.append(root)
  prev,pv=q,val
 return roots
